import math
import numpy as np
from typing import List, Dict, Any, Tuple

_global_decel_per_frame: float | None = None
_global_radius: float | None = None


def _compute_global_constants(doc: Dict[str, Any]) -> Tuple[float, float]:
    """Compute deceleration per frame and common radius from all scopes."""
    global _global_decel_per_frame, _global_radius
    if _global_decel_per_frame is not None and _global_radius is not None:
        return _global_decel_per_frame, _global_radius

    # ---- deceleration per frame ---------------------------------------------
    decels: list[float] = []
    for node in doc["nodes"]:
        if node.get("kind") != "table" or ": Motion log" not in node.get("title", ""):
            continue
        rows = node.get("table", {}).get("rows", [])
        by_obj: dict[str, list[Tuple[float, float]]] = {}
        for r in rows:
            if not r or len(r) < 7:
                continue
            f, v = float(r[0]), float(r[6])
            oid = r[1].split()[0]
            by_obj.setdefault(oid, []).append((f, v))
        for lst in by_obj.values():
            lst.sort(key=lambda x: x[0])
            for i in range(1, len(lst)):
                f1, v1 = lst[i - 1]
                f2, v2 = lst[i]
                dt = f2 - f1
                if dt <= 0 or v1 <= v2:
                    continue
                decels.append((v1 - v2) / dt)
    decel_per_frame = float(np.median(decels)) if decels else 0.01

    # ---- common radius (half of median collision distance) --------------------
    dists: list[float] = []
    for node in doc["nodes"]:
        title = node.get("title", "")
        if not title.startswith("Video") or ": Events" not in title:
            continue
        scope = title.split(":")[0]
        evs = observed_events(doc, scope)
        if not evs:
            continue
        mnode = _find_child_table(doc, node_by_title(doc, scope), ": Motion log")
        if not mnode:
            continue
        rows = mnode.get("table", {}).get("rows", [])
        pos_map: dict[tuple[int, str], tuple[float, float]] = {}
        for r in rows:
            if not r or len(r) < 7:
                continue
            f = int(round(float(r[0])))
            oid = r[1].split()[0]
            pos_map[(f, oid)] = (float(r[2]), float(r[3]))
        for ev in evs:
            if ev["kind"] != "collision" or len(ev["participants"]) < 2:
                continue
            f = int(round(ev["time"]))
            a, b = ev["participants"][:2]
            pa = pos_map.get((f, a))
            pb = pos_map.get((f, b))
            if pa and pb:
                dists.append(math.dist(pa, pb))
    radius = float(np.median(dists) / 2) if dists else 0.21

    _global_decel_per_frame = decel_per_frame
    _global_radius = radius
    return decel_per_frame, radius


def simulate(
    doc: Dict[str, Any],
    scope: str,
    removed=(),
    horizon=None,
    start=0.0,
) -> List[Dict[str, Any]]:
    """
    Forward‑model simulation for the scope *scope*.

    Parameters
    ----------
    doc       : document dictionary
    scope     : title of the scope (e.g. 'Video 12345')
    removed   : iterable of entity ids that are absent for the entire run
    horizon   : simulation end time; if None, use recorded_end(doc, scope)
    start     : simulation start time

    Returns
    -------
    List[Dict[str, Any]]  -- events occurring after *start*.
    Each event has keys: 'time', 'kind', 'participants'.
    """
    decel_per_frame, common_radius = _compute_global_constants(doc)

    node = node_by_title(doc, scope)
    if not node:
        return []

    mnode = _find_child_table(doc, node, ": Motion log")
    if not mnode or "table" not in mnode:
        return []

    rows = mnode["table"].get("rows", [])
    obj_rows: dict[str, list[Tuple[float, float, float, float, float, float]]] = {}
    for r in rows:
        if not r or len(r) < 7:
            continue
        f = float(r[0])
        oid = r[1].split()[0]
        x = float(r[2])
        y = float(r[3])
        vx = float(r[4])
        vy = float(r[5])
        obj_rows.setdefault(oid, []).append((f, x, y, vx, vy, _))
    for lst in obj_rows.values():
        lst.sort(key=lambda x: x[0])

    if horizon is None:
        horizon = recorded_end(doc, scope)

    dt = 0.01  # smaller step for better contact detection
    t = float(start)

    # positions and velocities of active bodies
    bodies: dict[str, dict[str, np.ndarray]] = {}
    entry_time: dict[str, float] = {oid: lst[0][0] for oid, lst in obj_rows.items()}

    # initialise bodies that exist at start
    for oid, f_ent in entry_time.items():
        if oid in removed:
            continue
        if f_ent <= start:
            pos, vel = _state_at_time_helper(oid, start, obj_rows, decel_per_frame)
            bodies[oid] = {"pos": pos, "vel": vel}

    pair_contact: dict[tuple[str, str], bool] = {}
    events: List[Dict[str, Any]] = []

    # ---- helper: interpolate/extrapolate state at any time ----
    def _state_at_time_helper(
        oid: str,
        cur_t: float,
        obj_rows_local: dict[str, list[Tuple[float, float, float, float, float, float]]],
        decel: float,
    ) -> Tuple[np.ndarray, np.ndarray]:
        lst = obj_rows_local[oid]
        if cur_t <= lst[0][0]:
            return np.array([lst[0][1], lst[0][2]]), np.array([lst[0][3], lst[0][4]])
        if cur_t >= lst[-1][0]:
            f1, x1, y1, vx1, vy1, _ = lst[-2]
            f2, x2, y2, vx2, vy2, _ = lst[-1]
            dt0 = cur_t - f2
            pos = np.array([x2, y2], dtype=float)
            vel = np.array([vx2, vy2], dtype=float)
            speed = np.linalg.norm(vel)
            if speed > 1e-8:
                unit = vel / speed
                new_speed = max(speed - decel * dt0, 0.0)
                new_vel = unit * new_speed
                new_pos = pos + vel * dt0 - 0.5 * decel * dt0**2 * unit
                return new_pos, new_vel
            return pos, np.array([0.0, 0.0])
        for i in range(len(lst) - 1):
            f1, x1, y1, vx1, vy1, _ = lst[i]
            f2, x2, y2, vx2, vy2, _ = lst[i + 1]
            if f1 <= cur_t <= f2:
                frac = (cur_t - f1) / (f2 - f1) if f2 > f1 else 0.0
                pos = np.array([x1, y1]) + frac * (np.array([x2, y2]) - np.array([x1, y1]))
                vel = np.array([vx1, vy1]) + frac * (np.array([vx2, vy2]) - np.array([vx1, vy1]))
                return pos, vel
        return np.array([lst[-1][1], lst[-1][2]]), np.array([lst[-1][3], lst[-1][4]])

    while t <= horizon + 1e-9:
        # 1. activate new bodies that have entered by this time
        for oid, f_ent in entry_time.items():
            if oid in removed or oid in bodies:
                continue
            if t >= f_ent - 1e-9:
                pos, vel = _state_at_time_helper(oid, f_ent, obj_rows, decel_per_frame)
                bodies[oid] = {"pos": pos, "vel": vel}

        # 2. update all active bodies using deceleration
        for bd in bodies.values():
            vel = bd["vel"]
            speed = np.linalg.norm(vel)
            if speed > 1e-8:
                unit = vel / speed
                new_speed = max(speed - decel_per_frame * dt, 0.0)
                new_vel = unit * new_speed
                bd["pos"] = bd["pos"] + vel * dt - 0.5 * decel_per_frame * dt**2 * unit
                bd["vel"] = new_vel

        # 3. detect collisions (perfectly elastic)
        ids = list(bodies.keys())
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                a_id = ids[i]
                b_id = ids[j]
                if a_id in removed or b_id in removed:
                    continue
                pa = bodies[a_id]["pos"]
                pb = bodies[b_id]["pos"]
                dist = np.linalg.norm(pa - pb)
                threshold = 2 * common_radius
                pair_key = tuple(sorted((a_id, b_id)))
                in_contact = pair_contact.get(pair_key, False)

                if dist <= threshold:
                    if not in_contact:
                        # Only record when at least one body is moving
                        speed_a = np.linalg.norm(bodies[a_id]["vel"])
                        speed_b = np.linalg.norm(bodies[b_id]["vel"])
                        if speed_a > 0.1 or speed_b > 0.1:
                            if t > start + 1e-9:
                                events.append(
                                    {
                                        "time": round(t, 5),
                                        "kind": "collision",
                                        "participants": list(pair_key),
                                    }
                                )
                        # Resolve velocities elastically (unit mass)
                        normal = pa - pb
                        if np.linalg.norm(normal) > 1e-8:
                            normal = normal / np.linalg.norm(normal)
                            va = bodies[a_id]["vel"]
                            vb = bodies[b_id]["vel"]
                            va_n = np.dot(va, normal)
                            vb_n = np.dot(vb, normal)
                            bodies[a_id]["vel"] = va - normal * va_n + normal * vb_n
                            bodies[b_id]["vel"] = vb - normal * vb_n + normal * va_n
                    pair_contact[pair_key] = True
                else:
                    pair_contact[pair_key] = False

        t += dt

    events.sort(key=lambda e: e["time"])
    return events

import re
from typing import Dict, List, Any

# ------------------------------------------------------------------
# Helpers (assumed to be available in the sandbox)
# ------------------------------------------------------------------
# def node_by_title(doc, title):    # returns node dict or None
# def children(doc, node):          # returns list of child node dicts
# def scope_nodes(doc, scope):      # returns list of child nodes of the scope node


def _find_child_list(doc: Dict[str, Any], parent: Dict[str, Any], suffix: str) -> Dict[str, Any]:
    """Return the child list node whose title ends with `suffix`."""
    for child in children(doc, parent):
        if child.get("kind") == "list" and child.get("title", "").endswith(suffix):
            return child
    return None


def _find_child_table(doc: Dict[str, Any], parent: Dict[str, Any], suffix: str) -> Dict[str, Any]:
    """Return the child table node whose title ends with `suffix`."""
    for child in children(doc, parent):
        if child.get("kind") == "table" and child.get("title", "").endswith(suffix):
            return child
    return None


