def simulate(
    doc: Dict[str, Any],
    scope: str,
    removed=(),
    horizon=None,
    start=0.0,
) -> List[Dict[str, Any]]:
    """
    Forward‑model simulation for the scope *scope*.

    Returns a list of collision events that occur after *start*. Each event has
    keys: 'time', 'kind', 'participants' (sorted list of ids).
    """
    decel_per_frame, common_radius = _compute_global_constants(doc)

    node = node_by_title(doc, scope)
    if not node:
