                pa, pb = bodies[a_id]["pos"], bodies[b_id]["pos"]
                dist = np.linalg.norm(pa - pb)
                threshold = 2 * common_radius
                pair_key = tuple(sorted((a_id, b_id)))
                in_contact = pair_contact.get(pair_key, False)

                if dist <= threshold:
                    if not in_contact:
                        # record only when at least one body is moving
                        if (
                            np.linalg.norm(bodies[a_id]["vel"]) > 0.1
                            or np.linalg.norm(bodies[b_id]["vel"]) > 0.1
                        ):
                            if t > start + 1e-9:
                                events.append(
                                    {
                                        "time": round(t, 5),
                                        "kind": "collision",
                                        "participants": list(pair_key),
                                    }
                                )
                        # elastic collision resolution for equal masses
                        normal = pa - pb
                        if np.linalg.norm(normal) > 1e-8:
                            normal = normal / np.linalg.norm(normal)
                            va, vb = bodies[a_id]["vel"], bodies[b_id]["vel"]
                            va_n = np.dot(va, normal)
                            vb_n = np.dot(vb, normal)
                            bodies[a_id]["vel"] = va - normal * va_n + normal * vb_n
                            bodies[b_id]["vel"] = vb - normal * vb_n + normal * va_n
                    pair_contact[pair_key] = True
                else:
                    pair_contact[pair_key] = False

        t += dt

    events.sort(key=lambda e: e["time"])
    return events

# Block 1: Estimate average deceleration across all scopes
import math, re
def gather_deceleration(doc):
    decs = []
    for scope_node in doc['nodes']:
        if scope_node.get('kind') != 'text':
            continue
        if not re.match(r'Video \d+', scope_node.get('title', '')):
            continue
        motion_node = _find_child_table(doc, scope_node, ': Motion log')
        if not motion_node:
            continue
        rows = motion_node['table'].get('rows', [])
        recs = {}
        for r in rows:
            if not r:
                continue
            frame = float(r[0]); obj_id = r[1].split()[0]
            recs.setdefault(obj_id, []).append(
                {'frame': frame, 'vx': float(r[4]), 'vy': float(r[5])}
            )
        for lst in recs.values():
            lst.sort(key=lambda t: t['frame'])
            for i in range(1, len(lst)):
                prev, cur = lst[i-1], lst[i]
                dt = cur['frame'] - prev['frame']
                if dt <= 0: continue
                sp_prev = math.hypot(prev['vx'], prev['vy'])
                sp_cur = math.hypot(cur['vx'], cur['vy'])
                delta = (sp_prev - sp_cur) / dt
                if delta > 0:
                    decs.append(delta)
    return decs

dec_vals = gather_deceleration(doc)
print("Scope count:", len([n for n in doc['nodes'] if n['kind']=='text' and re.match(r'Video \\d+', n['title'])]))
print("Number of decel samples:", len(dec_vals))
print("Avg decel:", sum(dec_vals)/len(dec_vals) if dec_vals else None)
print("Min decel:", min(dec_vals) if dec_vals else None)
print("Max decel:", max(dec_vals) if dec_vals else None)


# Block 2: Estimate collision radius from recorded collisions
def gather_radius(doc):
    rads = []
    for scope_node in doc['nodes']:
        if scope_node.get('kind') != 'text':
            continue
        if not re.match(r'Video \d+', scope_node.get('title', '')):
            continue
        evs = observed_events(doc, scope_node['title'])
        motion_node = _find_child_table(doc, scope_node, ': Motion log')
        rows = motion_node['table'].get('rows', []) if motion_node else []
        for ev in evs:
            if ev['kind'] != 'collision':
                continue
            time = ev['time']
            ids = ev['participants']
            def row_for(o_id, f):
                for rr in rows:
                    if float(rr[0]) != f:
                        continue
                    if rr[1].startswith(o_id + ' '):
                        return rr
                return None
            r1, r2 = row_for(ids[0], time), row_for(ids[1], time)
            if not r1 or not r2:
                continue
            x1, y1 = float(r1[2]), float(r1[3])
            x2, y2 = float(r2[2]), float(r2[3])
            dist = math.hypot(x1-x2, y1-y2)
            rads.append(dist/2.0)
    return rads

rad_vals = gather_radius(doc)
print("Number of recorded collision radii:", len(rad_vals))
print("Avg radius:", sum(rad_vals)/len(rad_vals) if rad_vals else None)
print("Min radius:", min(rad_vals) if rad_vals else None)
print("Max radius:", max(rad_vals) if rad_vals else None)


